(function(){
  /* Caducidad por plataforma, en días. Sale de la velocidad medida de cada una.
     Ver ~/.claude/rwadar-data/03-frescura.md */
  var TTL = { 'Prosegur':1, 'Midas':3, 'Hausera':3, 'Brickwise':5, 'Alius':7, 'Spiko':7,
              'Reental':14, 'Aktionariat':30 };

  /* Producto PERMANENTE (Tipo A del contrato de oferta): siempre comprable, no tiene ventana.
     Cuando caduca, lo que caduca es la CIFRA, no la oferta: la ficha se queda y el número se tacha. */
  var PERM = { 'Prosegur':1, 'Midas':1 };

  // Ordenar por puntuacion y renumerar. La posicion sale del DATO, no del orden en que
  // se escribieron las tarjetas: asi actualizar una cifra nunca obliga a mover HTML.
  (function(){
    var cont = document.getElementById('rowsYield');
    if (!cont) return;
    var filas = Array.prototype.slice.call(cont.querySelectorAll('.row'));
    filas.sort(function(a, b){ return parseFloat(b.dataset.score) - parseFloat(a.dataset.score); });
    filas.forEach(function(f, i){
      cont.appendChild(f);
      var r = f.querySelector('.rank');
      if (r) r.textContent = (i + 1 < 10 ? '0' : '') + (i + 1);
    });
  })();

  var cards = Array.prototype.slice.call(document.querySelectorAll('.row, .vcard'));
  var chips = Array.prototype.slice.call(document.querySelectorAll('.chip'));
  var gate  = document.getElementById('onlyES');
  var tally = document.getElementById('tally');
  var emptyYield = document.getElementById('emptyYield');
  var emptyValue = document.getElementById('emptyValue');
  var current = 'all';
  var HOY = new Date(); HOY.setHours(0,0,0,0);

  function ttlDe(card){
    var p = (card.querySelector('.plat') || {}).textContent || '';
    for (var k in TTL) { if (p.indexOf(k) !== -1) return TTL[k]; }
    return 7;
  }
  function esPerm(card){
    var p = (card.querySelector('.plat') || {}).textContent || '';
    for (var k in PERM) { if (p.indexOf(k) !== -1) return true; }
    return false;
  }
  function dias(iso){
    var d = new Date(iso + 'T00:00:00');
    return Math.max(0, Math.round((HOY - d) / 86400000));
  }
  function texto(n){
    if (n === 0) return 'verificado hoy';
    if (n === 1) return 'verificado ayer';
    return 'verificado hace ' + n + ' días';
  }

  /* Envejecer cada ficha con la fecha que lleva dentro, no con texto escrito a mano */
  cards.forEach(function(c){
    var chip = c.querySelector('.f.age');
    if (!chip) return;
    var n = dias(chip.dataset.ver), ttl = ttlDe(c);
    var estado = n <= ttl ? 'ok' : (n <= ttl * 2 ? 'warn' : 'stop');
    chip.classList.add(estado);
    c.dataset.perm = esPerm(c) ? '1' : '0';
    chip.textContent = texto(n) + (estado !== 'stop' ? '' : (c.dataset.perm === '1' ? ' · cifra sin verificar' : ' · caducada'));
    if (estado === 'stop' && c.dataset.perm === '1') c.classList.add('stale');
    chip.title = 'Esta plataforma caduca a los ' + ttl + ' días';
    c.dataset.estado = estado;
    c.dataset.dias = n;
  });

  function visible(c, f){
    /* Caducada: fuera del escaparate — salvo los permanentes, que siguen comprables */
    if (c.dataset.estado === 'stop' && c.dataset.perm !== '1') return false;
    if (gate.checked && c.dataset.es !== '1') return false;
    if (f === 'eu') return c.dataset.eu === '1';
    if (f === 'noladrillo') return c.dataset.brick === '1';
    if (f === 'aldia') return c.dataset.estado === 'ok';
    return true;
  }
  function apply(){
    var shown = 0, y = 0, v = 0;
    cards.forEach(function(c){
      var ok = visible(c, current);
      c.classList.toggle('hidden', !ok);
      if (ok){ shown++; c.classList.contains('row') ? y++ : v++; }
    });
    tally.textContent = 'Mostrando ' + shown + ' de ' + cards.length;
    emptyYield.classList.toggle('hidden', y > 0);
    emptyValue.classList.toggle('hidden', v > 0);
  }

  /* Contadores vivos: se calculan al abrir la página, no se escriben a mano */
  var retiradas = cards.filter(function(c){ return c.dataset.estado === 'stop' && c.dataset.perm !== '1'; });
  var tachadas  = cards.filter(function(c){ return c.dataset.estado === 'stop' && c.dataset.perm === '1'; });
  var vigentes  = cards.filter(function(c){ return retiradas.indexOf(c) === -1; });
  var fresca = cards.filter(function(c){ return c.dataset.estado === 'ok'; }).length;
  var tibia  = cards.filter(function(c){ return c.dataset.estado === 'warn'; }).length;
  var cad    = retiradas.length;

  document.getElementById('cEs').textContent    = vigentes.filter(function(c){ return c.dataset.es === '1'; }).length;
  document.getElementById('cSin').textContent   = vigentes.filter(function(c){ return c.dataset.es !== '1'; }).length;
  document.getElementById('cFresca').textContent = fresca;
  document.getElementById('cTibia').textContent  = tibia;
  document.getElementById('cCad').textContent    = cad;
  document.getElementById('boxTibia').classList.toggle('hidden', tibia === 0);
  document.getElementById('boxCad').classList.toggle('hidden', cad === 0);

  /* Aviso de frescura, solo si hay algo que avisar */
  if (tibia || cad || tachadas.length){
    var partes = [];
    if (cad)      partes.push('<strong>' + cad + ' ' + (cad === 1 ? 'ficha ha caducado y se ha retirado' : 'fichas han caducado y se han retirado') + '</strong>');
    if (tachadas.length) partes.push(tachadas.length + ' ' + (tachadas.length === 1 ? 'sigue comprable pero con la cifra sin verificar' : 'siguen comprables pero con la cifra sin verificar'));
    if (tibia) partes.push(tibia + ' ' + (tibia === 1 ? 'está envejeciendo' : 'están envejeciendo'));
    document.getElementById('freshText').innerHTML =
      partes.join(' y ') + '. Cada plataforma tiene su propio plazo, medido por lo rápido que se mueve: el oro de Prosegur caduca en un día, Midas y Hausera en tres, Aktionariat en treinta. ' +
      'Esta página calcula la antigüedad cada vez que se abre, así que envejece sola en lugar de seguir diciendo «verificado hoy» para siempre. Toca barrido.';
    document.getElementById('freshBanner').hidden = false;
  }

  chips.forEach(function(chip){
    chip.addEventListener('click', function(){
      current = chip.dataset.filter;
      chips.forEach(function(c){ c.setAttribute('aria-pressed', String(c === chip)); });
      apply();
    });
  });
  gate.addEventListener('change', apply);
  apply();
})();


/* ================================================================
   SECUNDARIO EN VIVO
   El mercado de reventa de Reental permite que lo llame el navegador
   directamente (comprobado el 23/08/2026). Asi que en vez de servir
   una foto fija del libro, la pedimos al abrir la pagina.

   Lo que NO viene de la API y por eso se conserva de la tabla ya
   pintada: la rentabilidad nominal de cada inmueble (la publica su
   catalogo, no el mercado), la foto incrustada y el enlace a la ficha.
   Si la llamada falla, la tabla se queda tal cual estaba: nunca deja
   la seccion vacia.
   ================================================================ */
(function(){
  var API = 'https://backend.reentalp2p.com/graphql';
  var tabla = document.querySelector('#secundario tbody');
  var rotulo = document.querySelector('#secundario .count');
  if (!tabla) return;

  /* Cosechar lo curado de las filas ya pintadas: no duplicamos nada */
  var CUR = {};
  Array.prototype.forEach.call(tabla.querySelectorAll('tr'), function(tr){
    var tds = tr.querySelectorAll('td');
    if (tds.length < 8) return;
    var a = tds[0].querySelector('a');
    var img = tds[0].querySelector('img');
    var nombre = (tds[0].textContent || '').trim();
    CUR[llave(nombre)] = {
      n: nombre,
      img: img ? img.getAttribute('src') : null,
      ficha: a ? a.getAttribute('href') : null,
      raNom: parseFloat((tds[2].textContent || '').replace('%','').replace(',','.').trim()),
      reparto: (tds[6].textContent || '').trim()
    };
  });

  function llave(s){
    return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  }
  function esp(n, dec){
    return Number(n).toFixed(dec).replace('.', ',');
  }
  function miles(n){
    return Math.round(n).toLocaleString('es-ES');
  }

  var qLibro = 'query($i:GetOrdersDataInput!){getOrdersData(input:$i){... on MarketplaceOrdersData{numOrders items{propertyName amountSum numOrders prices{pricePerTokenMin pricePerTokenMax priceSum}}}}}';
  var qCruces = 'query($i:FinalizedOrdersPaginatedInput!){getFinalizedOrdersPaginated(input:$i){... on FinalizedOrderAssets{items{propertyName matchedPrice matchedUnixtime amount}}}}';

  function pedir(q, vars){
    return fetch(API, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({query: q, variables: vars})
    }).then(function(r){ return r.json(); });
  }

  Promise.all([
    pedir(qLibro,  {i:{limit:100, offset:0, excludeExpired:true}}),
    pedir(qCruces, {i:{limit:300, offset:0, orderBy:'matchedUnixtime', orderDirection:'DESC'}})
  ]).then(function(res){
    var libro = res[0].data.getOrdersData;
    var items = (libro && libro.items) || [];
    if (!items.length) throw new Error('libro vacio');

    /* ultimo cruce real por inmueble */
    var cruces = {};
    var HOY = Math.floor(Date.now()/1000);
    var hist = (res[1].data.getFinalizedOrdersPaginated && res[1].data.getFinalizedOrdersPaginated.items) || [];
    hist.forEach(function(o){
      if (!o.propertyName) return;
      var k = llave(o.propertyName);
      var t = parseInt(o.matchedUnixtime, 10);
      var am = parseFloat(o.amount)/1e18;
      if (!(am > 0)) return;
      var pt = (parseFloat(o.matchedPrice)/1e6) / am;
      if (!cruces[k]) cruces[k] = {ult:0, precio:null, ops30:0};
      if (HOY - t <= 30*86400) cruces[k].ops30++;
      if (t > cruces[k].ult){ cruces[k].ult = t; cruces[k].precio = pt; }
    });

    var filas = items.map(function(x){
      var k = llave(x.propertyName);
      var c = CUR[k] || {};
      var p = (x.prices && x.prices[0]) || {};
      var pide = p.pricePerTokenMin;
      var cr = cruces[k];
      return {
        k: k,
        n: c.n || x.propertyName,
        img: c.img || null,
        ficha: c.ficha || null,
        reparto: c.reparto || '',
        raNom: c.raNom,
        pide: pide,
        pideMax: p.pricePerTokenMax,
        fondo: p.priceSum || 0,
        tokens: x.amountSum || 0,
        ord: x.numOrders || 0,
        raAjust: (isFinite(c.raNom) && pide > 0) ? (c.raNom * 100 / pide) : null,
        ult: cr ? cr.precio : null,
        dias: cr ? Math.floor((HOY - cr.ult)/86400) : null,
        prima: (cr && cr.precio) ? ((pide/cr.precio - 1) * 100) : null
      };
    });

    filas.sort(function(a,b){
      if (a.raAjust === null) return 1;
      if (b.raAjust === null) return -1;
      return b.raAjust - a.raAjust;
    });

    tabla.innerHTML = filas.map(function(f){
      var foto = f.img ? '<img class="tmini" src="'+f.img+'" alt="" loading="lazy">' : '';
      var nom = f.ficha
        ? foto + '<a href="'+f.ficha+'" target="_blank" rel="noopener">'+f.n+'</a>'
        : foto + f.n;

      var aj = (f.raAjust === null)
        ? '<span class="pz">sin dato propio</span>'
        : '<strong>'+esp(f.raAjust,2)+' %</strong>';
      var nomPct = isFinite(f.raNom) ? esp(f.raNom,2)+' %' : '—';

      var precio = (f.pideMax > f.pide)
        ? esp(f.pide,2)+'–'+esp(f.pideMax,2)+' $'
        : esp(f.pide,2)+' $';

      var cruce;
      if (f.ult){
        var cls = f.prima <= 0 ? 'ok' : (f.prima < 5 ? '' : 'warn');
        var sig = f.prima > 0 ? '+' : '';
        var etq = Math.abs(f.prima) < 0.05 ? 'al mismo precio' : sig+esp(f.prima,1)+' %';
        var d = f.dias === 0 ? 'hoy' : (f.dias === 1 ? 'ayer' : 'hace '+f.dias+' d');
        cruce = esp(f.ult,2)+' $ <small>'+d+'</small><br><span class="pz '+cls+'">'+etq+'</span>';
      } else {
        cruce = '<span class="pz stop">sin cruce reciente</span>';
      }

      return '<tr>'+
        '<td>'+nom+'</td>'+
        '<td data-l="Ajustada">'+aj+'</td>'+
        '<td data-l="Anuncia">'+nomPct+'</td>'+
        '<td data-l="Pides hoy">'+precio+'</td>'+
        '<td data-l="Último cruce">'+cruce+'</td>'+
        '<td data-l="Fondo">'+esp(f.tokens,2)+' tok<br><small>'+miles(f.fondo)+' $ · '+f.ord+' ord</small></td>'+
        '<td data-l="Reparto">'+f.reparto+'</td>'+
        '<td><a class="mini" href="https://p2p.rnt.finance/" target="_blank" rel="noopener">Buscar en el P2P</a></td>'+
      '</tr>';
    }).join('');

    /* rotulos que dependen del libro */
    var hora = new Date().toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit'});
    if (rotulo) rotulo.textContent = filas.length + ' activos · Reental · libro en vivo, ' + hora;
    var cont = document.querySelector('#cSec');
    if (cont) cont.textContent = filas.length;
    var tam = document.getElementById('secTam');
    if (tam){
      var fondo = filas.reduce(function(s,f){ return s + f.fondo; }, 0);
      tam.textContent = libro.numOrders + ' órdenes y unos ' + miles(fondo) + ' $';
    }
    var sinCruce = filas.filter(function(f){ return !f.ult; }).length;
    var sc = document.getElementById('secSinCruce');
    if (sc) sc.textContent = sinCruce;
    var st = document.getElementById('secTotal');
    if (st) st.textContent = filas.length;
  }).catch(function(){
    /* silencio: se queda la tabla verificada a mano */
    if (rotulo && rotulo.textContent.indexOf('en vivo') < 0){
      rotulo.textContent = rotulo.textContent + ' · sin conexión con el mercado';
    }
  });
})();
